<!--
 * 异步任务监控面板
 *
 * <p>展示异步任务列表，支持查看任务详情、取消任务。
 * 顶部统计栏显示各状态任务计数，列表每 5 秒自动轮询刷新。
 *
 * <p>消费后端 AsyncTaskController 契约（auto-generated by bash/gen-contract.py）：
 * listActiveTasks() 获取活动任务列表，getTask() 获取单任务详情，cancelTask() 取消任务。
 *
 * @path apps/agent-web/src/views/async-task/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 异步任务监控面板
 * <p>消费后端 AsyncTaskController 契约（apps/agent-web/src/api/asyncTask.ts）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page } from '@ydsz/common-ui';
import {
  YdBadge,
  YdButton,
  YdCard,
  YdDrawer,
  YdDescriptions,
  YdDescriptionsItem,
  YdEmptyState,
  YdTable,
  YdTableColumn,
} from '@ydsz-core/ydsz-ui';
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import { createLogger } from '@ydsz/utils';
import { cancelTask, getTask, listActiveTasks } from '#/api/asyncTask';
import type { AsyncTaskVO } from '#/api/models';

const logger = createLogger('agent-async-task');

defineOptions({ name: 'AsyncTaskManagement' });

const { t } = useI18n();

/** 轮询间隔（毫秒） */
const POLL_INTERVAL = 5000;

/** 任务列表数据 */
const taskList = ref<AsyncTaskVO[]>([]);

/** 加载状态 */
const loading = ref(false);

/** 轮询定时器引用 */
let pollTimer: ReturnType<typeof setInterval> | null = null;

/** 详情抽屉可见性 */
const detailVisible = ref(false);

/** 当前选中的任务详情 */
const selectedTask = ref<AsyncTaskVO | null>(null);

/** 详情加载状态 */
const detailLoading = ref(false);

/** 待确认取消的任务 ID */
const pendingCancelId = ref<number | null>(null);

// ==================== 统计卡片 ====================

/** 统计各状态任务数量 */
const stats = computed(() => {
  const list = taskList.value;
  const active = list.filter((t) => !(t.isTerminal === true)).length;
  const completed = list.filter((t) => (t.status ?? '').toUpperCase() === 'COMPLETED').length;
  const failed = list.filter((t) => (t.status ?? '').toUpperCase() === 'FAILED').length;
  const running = list.filter((t) => (t.status ?? '').toUpperCase() === 'RUNNING').length;
  return { total: list.length, active, completed, failed, running };
});

// ==================== 状态处理 ====================

/**
 * 获取任务状态对应的 Badge variant
 *
 * @param status - 状态编码
 * @returns Badge variant 值
 */
function getStatusVariant(status: string): 'success' | 'danger' | 'warning' | 'info' | 'secondary' {
  switch ((status ?? '').toUpperCase()) {
    case 'COMPLETED':
      return 'success';
    case 'FAILED':
      return 'danger';
    case 'RUNNING':
      return 'warning';
    case 'PENDING':
      return 'info';
    case 'CANCELLED':
      return 'secondary';
    default:
      return 'info';
  }
}

/**
 * 判断任务是否可取消（PENDING 或 RUNNING 状态）
 *
 * @param task - 异步任务 VO
 * @returns 是否可取消
 */
function isCancelable(task: AsyncTaskVO): boolean {
  const status = (task.status ?? '').toUpperCase();
  return status === 'PENDING' || status === 'RUNNING';
}

// ==================== 时间格式化 ====================

/**
 * 格式化耗时：根据毫秒数生成可读字符串
 *
 * @param startedAt - 开始时间
 * @param completedAt - 完成时间（可选）
 * @returns 耗时字符串
 */
function formatDuration(startedAt?: string, completedAt?: string): string {
  if (!startedAt) { return '-'; }
  const start = new Date(startedAt).getTime();
  const end = completedAt ? new Date(completedAt).getTime() : Date.now();
  if (Number.isNaN(start) || Number.isNaN(end)) { return '-'; }
  const ms = end - start;
  if (ms < 0) { return '-'; }
  if (ms < 1000) { return `${ms}ms`; }
  const seconds = Math.floor(ms / 1000);
  if (seconds < 60) { return `${seconds}s`; }
  const minutes = Math.floor(seconds / 60);
  const remainSec = seconds % 60;
  if (minutes < 60) { return `${minutes}m ${remainSec}s`; }
  const hours = Math.floor(minutes / 60);
  const remainMin = minutes % 60;
  return `${hours}h ${remainMin}m`;
}

/**
 * 截断显示 taskId
 *
 * @param id - 任务 ID
 * @returns 截断后的字符串
 */
function truncateId(id?: number): string {
  if (id === undefined || id === null) { return '-'; }
  return String(id);
}

// ==================== 数据加载 ====================

/** 加载活动任务列表 */
async function loadTaskList(): Promise<void> {
  loading.value = true;
  try {
    const res = await listActiveTasks({});
    taskList.value = res ?? [];
  } catch (error) {
    logger.warn('加载异步任务列表失败: {}', error);
    taskList.value = [];
  } finally {
    loading.value = false;
  }
}

/** 加载任务详情并打开抽屉 */
async function handleViewDetail(row: AsyncTaskVO): Promise<void> {
  detailLoading.value = true;
  detailVisible.value = true;
  try {
    selectedTask.value = await getTask({ taskId: row.id ?? 0 });
  } catch (error) {
    logger.warn('获取任务详情失败: {}', error);
    selectedTask.value = row;
  } finally {
    detailLoading.value = false;
  }
}

/** 取消任务 */
async function handleCancel(row: AsyncTaskVO): Promise<void> {
  const taskId = row.id ?? 0;
  // 步骤1：二次确认
  try {
    await YdConfirm(
      `确定取消任务「${truncateId(row.id)}」吗？该操作不可撤销。`,
      '取消确认',
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消删除操作');
    return;
  }
  // 步骤2：执行取消 API
  pendingCancelId.value = taskId;
  try {
    await cancelTask({ taskId });
    showToast.success('任务已取消');
    await loadTaskList();
  } catch (error) {
    logger.warn('取消任务失败: {}', error);
  } finally {
    pendingCancelId.value = null;
  }
}

// ==================== 轮询控制 ====================

/** 启动轮询定时器 */
function startPolling(): void {
  stopPolling();
  pollTimer = setInterval(() => {
    void loadTaskList();
  }, POLL_INTERVAL);
}

/** 停止轮询定时器 */
function stopPolling(): void {
  if (pollTimer !== null) {
    clearInterval(pollTimer);
    pollTimer = null;
  }
}

/** 手动刷新 */
function handleManualRefresh(): void {
  void loadTaskList();
}

onMounted(() => {
  void loadTaskList();
  startPolling();
});

onBeforeUnmount(() => {
  stopPolling();
});
</script>

<template>
  <Page auto-content-height>
    <div class="space-y-4 p-4">
      <!-- 顶部统计栏 -->
      <div class="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
        <YdCard shadow="hover">
          <div class="flex items-center justify-between">
            <div>
              <p class="text-sm text-gray-500">活动任务数</p>
              <p class="mt-1 text-2xl font-bold text-blue-600">{{ stats.active }}</p>
            </div>
            <div class="rounded-full bg-blue-50 p-3">
              <span class="text-2xl text-blue-500">📋</span>
            </div>
          </div>
        </YdCard>

        <YdCard shadow="hover">
          <div class="flex items-center justify-between">
            <div>
              <p class="text-sm text-gray-500">已完成</p>
              <p class="mt-1 text-2xl font-bold text-green-600">{{ stats.completed }}</p>
            </div>
            <div class="rounded-full bg-green-50 p-3">
              <span class="text-2xl text-green-500">✅</span>
            </div>
          </div>
        </YdCard>

        <YdCard shadow="hover">
          <div class="flex items-center justify-between">
            <div>
              <p class="text-sm text-gray-500">运行中</p>
              <p class="mt-1 text-2xl font-bold text-orange-600">{{ stats.running }}</p>
            </div>
            <div class="rounded-full bg-orange-50 p-3">
              <span class="text-2xl text-orange-500">⚡</span>
            </div>
          </div>
        </YdCard>

        <YdCard shadow="hover">
          <div class="flex items-center justify-between">
            <div>
              <p class="text-sm text-gray-500">失败</p>
              <p class="mt-1 text-2xl font-bold text-red-600">{{ stats.failed }}</p>
            </div>
            <div class="rounded-full bg-red-50 p-3">
              <span class="text-2xl text-red-500">❌</span>
            </div>
          </div>
        </YdCard>
      </div>

      <!-- 任务列表 -->
      <YdCard>
        <div class="mb-4 flex items-center justify-between">
          <h3 class="text-base font-medium">活动任务列表</h3>
          <YdButton :loading="loading" size="sm" @click="handleManualRefresh">
            手动刷新
          </YdButton>
        </div>

        <YdTable :data="taskList" border stripe height="auto" :loading="loading">
          <YdTableColumn prop="id" label="Task ID" width="100" />
          <YdTableColumn prop="taskTypeDesc" label="任务类型" min-width="140" show-overflow-tooltip />
          <YdTableColumn label="状态" width="120">
            <template #default="{ row }">
              <YdBadge :variant="getStatusVariant(row.status ?? '')">
                {{ row.statusDesc ?? row.status ?? '-' }}
              </YdBadge>
            </template>
          </YdTableColumn>
          <YdTableColumn label="进度" width="120">
            <template #default="{ row }">
              <span>{{ row.progressPercent !== undefined && row.progressPercent !== null ? `${row.progressPercent}%` : '-' }}</span>
            </template>
          </YdTableColumn>
          <YdTableColumn prop="createdAt" label="创建时间" width="170" />
          <YdTableColumn label="耗时" width="120">
            <template #default="{ row }">
              {{ formatDuration(row.startedAt, row.isTerminal ? row.completedAt : undefined) }}
            </template>
          </YdTableColumn>
          <YdTableColumn :label="t('common.actions')" width="180" fixed="right">
            <template #default="{ row }">
              <div class="flex gap-1">
                <YdButton size="sm" variant="link" @click="handleViewDetail(row)">{{
                  '查看详情'
                }}</YdButton>
                <YdButton
                  v-if="isCancelable(row)"
                  size="sm"
                  variant="link"
                  class="text-destructive"
                  :loading="pendingCancelId === row.id"
                  @click="handleCancel(row)"
                >
                  {{ '取消' }}
                </YdButton>
              </div>
            </template>
          </YdTableColumn>

          <!-- 空态 -->
          <template #empty>
            <YdEmptyState description="暂无活动任务" />
          </template>
        </YdTable>
      </YdCard>
    </div>

    <!-- 任务详情抽屉 -->
    <YdDrawer v-model="detailVisible" title="任务详情" size="520px">
      <div v-if="detailLoading" class="flex items-center justify-center py-8">
        <span class="text-sm text-gray-500">加载中...</span>
      </div>
      <div v-else-if="selectedTask">
        <YdDescriptions :column="1" border>
          <YdDescriptionsItem label="Task ID">{{ selectedTask.id ?? '-' }}</YdDescriptionsItem>
          <YdDescriptionsItem label="任务类型">
            {{ selectedTask.taskTypeDesc ?? selectedTask.taskType ?? '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="状态">
            <YdBadge :variant="getStatusVariant(selectedTask.status ?? '')">
              {{ selectedTask.statusDesc ?? selectedTask.status ?? '-' }}
            </YdBadge>
          </YdDescriptionsItem>
          <YdDescriptionsItem label="进度">
            {{ selectedTask.progressPercent !== undefined && selectedTask.progressPercent !== null ? `${selectedTask.progressPercent}%` : '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="租户编码">
            {{ selectedTask.tenantCode ?? '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="触发用户">
            {{ selectedTask.userId ?? '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="创建时间">
            {{ selectedTask.createdAt ?? '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="开始时间">
            {{ selectedTask.startedAt ?? '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="完成时间">
            {{ selectedTask.completedAt ?? '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="过期时间">
            {{ selectedTask.expireAt ?? '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="重试次数">
            {{ selectedTask.retryCount !== undefined && selectedTask.retryCount !== null ? `${selectedTask.retryCount} / ${selectedTask.maxRetry ?? 0}` : '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="是否终态">
            {{ selectedTask.isTerminal ? '是' : '否' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="是否可重试">
            {{ selectedTask.isRetryable ? '是' : '否' }}
          </YdDescriptionsItem>
        </YdDescriptions>

        <!-- 输入参数 -->
        <div v-if="selectedTask.outputPayload" class="mt-4">
          <h4 class="mb-2 text-sm font-medium text-gray-700">输出结果</h4>
          <pre class="max-h-60 overflow-auto whitespace-pre-wrap break-all rounded border bg-gray-50 p-3 text-xs">{{ selectedTask.outputPayload }}</pre>
        </div>

        <!-- 错误信息 -->
        <div v-if="selectedTask.errorMessage" class="mt-4">
          <h4 class="mb-2 text-sm font-medium text-red-600">错误信息</h4>
          <div class="rounded border border-red-200 bg-red-50 p-3 text-sm text-red-700">
            <pre class="whitespace-pre-wrap break-all">{{ selectedTask.errorMessage }}</pre>
          </div>
        </div>
      </div>
    </YdDrawer>
  </Page>
</template>
